"""Regenerate docs/rules.md from the rule registry: python scripts/gen_rules_doc.py"""

from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / "src"))

from tfcheck.rules import all_rules  # noqa: E402

PROVIDERS = {"aws": "AWS", "azure": "Azure", "gcp": "Google Cloud"}


def render() -> str:
    rules = all_rules()
    out = [
        "# Rule reference",
        "",
        "<!-- Generated by scripts/gen_rules_doc.py. Do not edit by hand. -->",
        "",
        f"tfcheck ships {len(rules)} rules. Run `tfcheck explain <RULE-ID>` for the same text in a terminal.",
        "",
    ]
    for provider, label in PROVIDERS.items():
        group = [r for r in rules if r.provider == provider]
        out += [f"## {label}", "", "| ID | Severity | Title |", "|---|---|---|"]
        out += [f"| [{r.id}](#{r.id.lower()}) | {r.severity} | {r.title} |" for r in group]
        out.append("")
        for r in group:
            types = ", ".join(f"`{t}`" for t in r.resource_types)
            out += [
                f"### {r.id}",
                "",
                f"**{r.title}**  ",
                f"Severity: **{r.severity}** · Resources: {types}",
                "",
                r.description,
                "",
                "**Fix**",
                "",
            ]
            if r.fix_text:
                out += [r.fix_text, ""]
            if r.fix_code:
                out += ["```hcl", r.fix_code, "```", ""]
    return "\n".join(out)


if __name__ == "__main__":
    (ROOT / "docs" / "rules.md").write_text(render(), encoding="utf-8")
    print(f"wrote docs/rules.md ({len(all_rules())} rules)")
